insert into public.services (id, slug, terme, definition, texte, kurz, marge_terme, marge_texte, matieres, ordre, statut) values
  ('immobilier-patrimoine', '{"fr":"immobilier-et-patrimoine","de":"immobilien-und-vermoegen","en":"property-and-assets"}'::jsonb, '{"fr":"Immobilier et patrimoine","de":"Immobilien und Vermögen","en":"Property and assets"}'::jsonb, '{"fr":"Acheter, détenir, louer et transmettre un bien au Luxembourg quand on habite ailleurs.","de":"Eine Immobilie in Luxemburg kaufen, halten, vermieten und weitergeben, wenn man anderswo wohnt.","en":"Buying, holding, letting and passing on property in Luxembourg while living elsewhere."}'::jsonb, '{"fr":"Nous accompagnons l’achat depuis le compromis jusqu’à l’acte notarié, et nous vérifions avant la signature ce que la structure de détention coûtera plus tard en impôts. Pour les bailleurs, nous rédigeons les baux, encadrons les révisions de loyer et menons les procédures devant le juge de paix.","de":"Wir begleiten den Kauf vom Vorvertrag bis zur notariellen Urkunde und prüfen vor der Unterschrift, was die gewählte Haltestruktur später an Steuern kostet. Für Vermieter setzen wir die Mietverträge auf, begleiten Mietanpassungen und führen die Verfahren vor dem Friedensgericht.","en":"We accompany a purchase from the preliminary contract to the notarial deed, and we check before signature what the chosen ownership structure will cost in tax later on. For landlords we draft the leases, handle rent reviews and conduct proceedings before the magistrate’s court."}'::jsonb, '{"fr":"Acheter, détenir, louer","de":"Kaufen, halten, vermieten","en":"Buying, holding, letting"}'::jsonb, '{"fr":"Non-résidents","de":"Nichtansässige","en":"Non-residents"}'::jsonb, '{"fr":"La question la plus fréquente de l’Étude.","de":"Die häufigste Frage der Kanzlei.","en":"The firm’s most frequent question."}'::jsonb, '[{"fr":"Droit immobilier et patrimonial","de":"Immobilien- und Vermögensrecht","en":"Property and asset law","lb":null},{"fr":"Investissement immobilier et fiscalité immobilière","de":"Immobilieninvestition und Immobilienbesteuerung","en":"Property investment and property taxation","lb":null},{"fr":"Baux à loyer et baux à ferme","de":"Miet- und Pachtrecht","en":"Residential and agricultural leases","lb":null},{"fr":"Accompagnement de family office","de":"Family-Office-Betreuung","en":"Family office support","lb":null}]'::jsonb, 1, 'veroeffentlicht'),
  ('societes-fiscalite', '{"fr":"societes-et-fiscalite","de":"gesellschaften-und-steuern","en":"companies-and-tax"}'::jsonb, '{"fr":"Sociétés et fiscalité","de":"Gesellschaften und Steuern","en":"Companies and tax"}'::jsonb, '{"fr":"Constituer, domicilier et faire vivre une société luxembourgeoise, et savoir ce qu’elle déclenche dans votre pays.","de":"Eine luxemburgische Gesellschaft gründen, domizilieren und führen — und wissen, was sie in Ihrem Land auslöst.","en":"Setting up, domiciling and running a Luxembourg company, and knowing what it triggers in your own country."}'::jsonb, '{"fr":"Nous constituons des sociétés luxembourgeoises, notamment des SOPARFI et des sociétés de gestion de patrimoine familial, assurons la domiciliation et tenons les obligations courantes : assemblées, comptes, registre des bénéficiaires effectifs. En amont, nous examinons la convention fiscale applicable entre le Luxembourg et votre pays de résidence, parce que c’est elle, et non le choix de la forme sociale, qui décide du résultat.","de":"Wir gründen luxemburgische Gesellschaften, darunter SOPARFI und Gesellschaften zur Verwaltung von Familienvermögen, übernehmen die Domizilierung und halten die laufenden Pflichten ein: Versammlungen, Abschlüsse, Register der wirtschaftlich Berechtigten. Vorher sehen wir uns das Doppelbesteuerungsabkommen zwischen Luxemburg und Ihrem Wohnsitzstaat an, denn darüber entscheidet sich das Ergebnis — nicht über die Wahl der Rechtsform.","en":"We incorporate Luxembourg companies, including SOPARFIs and family wealth management companies, handle domiciliation and keep up the running obligations: meetings, accounts, register of beneficial owners. Beforehand we look at the double tax treaty between Luxembourg and your country of residence, because that is what decides the outcome — not the choice of corporate form."}'::jsonb, '{"fr":"Créer, domicilier, imposer","de":"Gründen, domizilieren, versteuern","en":"Forming, domiciling, taxing"}'::jsonb, '{"fr":"SOPARFI · SPF","de":"SOPARFI · SPF","en":"SOPARFI · SPF"}'::jsonb, '{"fr":"Deux dossiers du fonds documentaire portent sur ces formes.","de":"Zwei Fachdossiers der Bibliothek behandeln diese Formen.","en":"Two briefings in the library deal with these forms."}'::jsonb, '[{"fr":"Droit des sociétés luxembourgeois","de":"Luxemburgisches Gesellschaftsrecht","en":"Luxembourg company law","lb":null},{"fr":"Constitution de sociétés","de":"Gesellschaftsgründung","en":"Company formation","lb":null},{"fr":"Domiciliation de sociétés","de":"Domizilierung von Gesellschaften","en":"Company domiciliation","lb":null},{"fr":"Fiscalité internationale","de":"Internationales Steuerrecht","en":"International taxation","lb":null},{"fr":"Fusions et acquisitions","de":"Fusionen und Übernahmen","en":"Mergers and acquisitions","lb":null},{"fr":"Droit bancaire et financier","de":"Bank- und Finanzrecht","en":"Banking and finance law","lb":null}]'::jsonb, 2, 'veroeffentlicht'),
  ('successions', '{"fr":"successions","de":"erbfolge","en":"inheritance"}'::jsonb, '{"fr":"Successions","de":"Erbfolge","en":"Inheritance"}'::jsonb, '{"fr":"Régler une succession qui touche le Luxembourg et au moins un autre pays.","de":"Einen Erbfall regeln, der Luxemburg und mindestens ein weiteres Land berührt.","en":"Settling an estate that touches Luxembourg and at least one other country."}'::jsonb, '{"fr":"Nous déterminons quelle loi s’applique à la succession, réunissons les pièces d’état civil de plusieurs pays et conduisons le partage, y compris lorsque les héritiers ne s’entendent pas. Quand un bien immobilier luxembourgeois entre dans une succession ouverte à l’étranger, nous faisons le lien avec le notaire et l’avocat de l’autre pays.","de":"Wir klären, welches Recht auf den Erbfall anwendbar ist, tragen die Personenstandsurkunden aus mehreren Ländern zusammen und führen die Auseinandersetzung — auch dann, wenn die Erben sich nicht einig sind. Gehört eine luxemburgische Immobilie zu einem im Ausland eröffneten Nachlass, halten wir die Verbindung zum dortigen Notar und Anwalt.","en":"We establish which law applies to the estate, gather civil status records from several countries and carry the division through, including where the heirs disagree. Where Luxembourg property forms part of an estate opened abroad, we keep the link to the notary and lawyer in the other country."}'::jsonb, '{"fr":"Successions transfrontalières","de":"Nachlass über Grenzen","en":"Cross-border estates"}'::jsonb, '{"fr":"Deux pays au moins","de":"Mindestens zwei Länder","en":"At least two countries"}'::jsonb, '{"fr":"Presque chaque dossier de l’Étude.","de":"Fast jedes Mandat der Kanzlei.","en":"Almost every matter the firm handles."}'::jsonb, '[{"fr":"Successions internationales","de":"Internationales Erbrecht","en":"International succession","lb":null},{"fr":"Successions luxembourgeoises","de":"Luxemburgisches Erbrecht","en":"Luxembourg succession law","lb":null}]'::jsonb, 3, 'veroeffentlicht'),
  ('creances-droits', '{"fr":"creances-et-droits","de":"forderungen-und-rechte","en":"claims-and-rights"}'::jsonb, '{"fr":"Créances et droits","de":"Forderungen und Rechte","en":"Claims and rights"}'::jsonb, '{"fr":"Faire rentrer ce qui vous est dû, et protéger ce qui vous appartient.","de":"Hereinholen, was Ihnen zusteht, und schützen, was Ihnen gehört.","en":"Recovering what you are owed, and protecting what is yours."}'::jsonb, '{"fr":"Nous recouvrons les créances de créanciers luxembourgeois auprès de débiteurs établis à l’étranger — à l’amiable, et devant les tribunaux lorsqu’il le faut. L’Étude représente au Luxembourg le groupe Intrum Justitia et la League International for Creditors, et dépose marques et brevets pour le Benelux et pour l’Europe.","de":"Wir treiben Forderungen luxemburgischer Gläubiger gegen Schuldner im Ausland ein — außergerichtlich, und wenn nötig vor Gericht. Die Kanzlei vertritt Intrum Justitia und die League International for Creditors in Luxemburg und meldet Marken und Patente für Benelux und Europa an.","en":"We recover the claims of Luxembourg creditors against debtors established abroad — out of court, and before the courts where necessary. The firm represents Intrum Justitia and the League International for Creditors in Luxembourg, and files trademarks and patents for Benelux and for Europe."}'::jsonb, '{"fr":"Recouvrer, protéger","de":"Eintreiben, schützen","en":"Recovering, protecting"}'::jsonb, '{"fr":"Intrum Justitia · LIC","de":"Intrum Justitia · LIC","en":"Intrum Justitia · LIC"}'::jsonb, '{"fr":"Mandats de représentation au Luxembourg.","de":"Vertretungsmandate in Luxemburg.","en":"Representation mandates in Luxembourg."}'::jsonb, '[{"fr":"Recouvrement de créances, amiable et judiciaire","de":"Forderungseinzug, außergerichtlich und gerichtlich","en":"Debt recovery, out of court and judicial","lb":null},{"fr":"Dépôt de marques et de brevets, Benelux et Europe","de":"Marken- und Patentanmeldung, Benelux und Europa","en":"Trademark and patent filing, Benelux and Europe","lb":null},{"fr":"Propriété intellectuelle et industrielle","de":"Geistiges und gewerbliches Eigentum","en":"Intellectual and industrial property","lb":null},{"fr":"Droit des assurances et de l’indemnisation","de":"Versicherungs- und Entschädigungsrecht","en":"Insurance and compensation law","lb":null},{"fr":"Droit civil et commercial","de":"Zivil- und Handelsrecht","en":"Civil and commercial law","lb":null},{"fr":"Droit de la responsabilité","de":"Haftungsrecht","en":"Liability law","lb":null}]'::jsonb, 4, 'veroeffentlicht')
